      <h3>Current Count: {count}</h3>
      <button 
        onClick={() => setCount(prev => prev + 1)}
        style={{ padding: '0.5rem 1rem', background: '#6366f1', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
      >
        Increment (+1)
      </button>
    </div>
  );
}
